"""Validate external metadata only; raw packet/frame bytes stay opaque."""
import json,re
MAX=2**62-1
HEX=re.compile(r'(?:[0-9a-fA-F]{2})*\Z',re.ASCII)
def pairs(items):
    out={}
    for k,v in items:
        if k in out:raise ValueError('duplicate decoded key')
        out[k]=v
    return out
def num(x,limit=MAX):return type(x) is int and 0<=x<=limit
def shape(x,names):return type(x) is dict and x.keys()==set(names.split())
def hex_bytes(x,low=0,high=8*1024**2):
    if type(x) is not str or not HEX.fullmatch(x) or not low<=len(x)//2<=high:raise ValueError('hex')
    return bytes.fromhex(x)
