"""Visible scored-process profile: Java threads are allowed, child processes are not."""
import ctypes,errno,os,platform,resource,signal,sys

def restrict(cpu=60):
    if os.geteuid()==0 or platform.machine()!='x86_64':raise RuntimeError('nonroot Linux x86_64 required')
    for key,pair in [(resource.RLIMIT_AS,(4*1024**3,)*2),(resource.RLIMIT_CPU,(cpu,cpu+1)),(resource.RLIMIT_NOFILE,(128,128)),(resource.RLIMIT_NPROC,(64,64)),(resource.RLIMIT_FSIZE,(64*1024**2,)*2),(resource.RLIMIT_CORE,(0,0))]:resource.setrlimit(key,pair)
